import{_ as l,a0 as i,w as p,s as r,ao as g,I as o,x as s,a1 as e,A as n}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const x=JSON.parse('{"title":"配置 logrotate 的終極指導 | LCTT x X-CMD","titleTemplate":false,"description":"配置 logrotate 的終極指導 | LCTT (201702) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"配置 logrotate 的終極指導 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"配置 logrotate 的終極指導 | LCTT (201702) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201702/20170122 Ultimate guide to configure logrotate utility","title":"配置 logrotate 的終極指導","tag":"201702","desc":""},"relativePath":"201702/20170122 Ultimate guide to configure logrotate utility.md","filePath":"[post].md"}'),d={name:"201702/20170122 Ultimate guide to configure logrotate utility.md"};function c(u,t,h,k,m,b){const a=i("Link");return p(),r("div",null,[t[13]||(t[13]=g(`<h1 id="配置-logrotate-的終極指導" tabindex="-1">配置 logrotate 的終極指導 <a class="header-anchor" href="#配置-logrotate-的終極指導" aria-label="Permalink to “配置 logrotate 的終極指導”">​</a></h1><p>一般來説，日誌是任何故障排除過程中非常重要的一部分，但這些日誌會隨着時間增長。在這種情況下，我們需要手動執行日誌清理以回收空間，這是一件繁瑣的管理任務。為了解決這個問題，我們可以在 Linux 中配置 logrotate 程序，它可以自動執行日誌文件的輪換、壓縮、刪除和用郵件發出。</p><p>我們可以配置 logrotate 程序，以便每個日誌文件可以在每天、每週、每月或當它變得太大時處理。</p><h3 id="logrotate-是如何工作的" tabindex="-1">logrotate 是如何工作的 <a class="header-anchor" href="#logrotate-是如何工作的" aria-label="Permalink to “logrotate 是如何工作的”">​</a></h3><p>默認情況下，logrotate 命令作為放在 <code>/etc/cron.daily</code> 中的 cron 任務，每天運行一次，它會幫助你設置一個策略，其中超過某個時間或大小的日誌文件被輪換。</p><p>命令： <code>/usr/sbin/logrotate</code></p><p>配置文件： <code>/etc/logrotate.conf</code></p><p>這是 logrotate 的主配置文件。logrotate 還在 <code>/etc/logrotate.d/</code> 中存儲了特定服務的配置。確保下面的那行包含在 <code>/etc/logrotate.conf</code> 中，以讀取特定服務日誌配置。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>include  /etc/logrotate.d\`</span></span></code></pre></div><p>logrotate 歷史： <code>/var/lib/logrotate.status</code></p><p>重要的 logrotate 選項：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>compress             --&gt; 壓縮日誌文件的所有非當前版本</span></span>
<span class="line"><span>daily,weekly,monthly --&gt; 按指定計劃輪換日誌文件</span></span>
<span class="line"><span>delaycompress        --&gt; 壓縮所有版本，除了當前和下一個最近的</span></span>
<span class="line"><span>endscript            --&gt; 標記 prerotate 或 postrotate 腳本的結束</span></span>
<span class="line"><span>errors &quot;emailid&quot;     --&gt; 給指定郵箱發送錯誤通知</span></span>
<span class="line"><span>missingok            --&gt; 如果日誌文件丟失，不要顯示錯誤</span></span>
<span class="line"><span>notifempty           --&gt; 如果日誌文件為空，則不輪換日誌文件</span></span>
<span class="line"><span>olddir &quot;dir&quot;         --&gt; 指定日誌文件的舊版本放在 “dir” 中</span></span>
<span class="line"><span>postrotate           --&gt; 引入一個在日誌被輪換後執行的腳本</span></span>
<span class="line"><span>prerotate            --&gt; 引入一個在日誌被輪換前執行的腳本</span></span>
<span class="line"><span>rotate &#39;n&#39;           --&gt; 在輪換方案中包含日誌的 n 個版本</span></span>
<span class="line"><span>sharedscripts        --&gt; 對於整個日誌組只運行一次腳本</span></span>
<span class="line"><span>size=&#39;logsize&#39;       --&gt; 在日誌大小大於 logsize（例如 100K，4M）時輪換</span></span></code></pre></div><h3 id="配置" tabindex="-1">配置 <a class="header-anchor" href="#配置" aria-label="Permalink to “配置”">​</a></h3><p>讓我們為我們自己的示例日誌文件 <code>/tmp/sample_output.log</code> 配置 logrotate。</p><p>第一步：在 <code>/etc/logrotate.conf</code> 中添加以下行。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>/tmp/sample_output.log {</span></span>
<span class="line"><span>  size 1k</span></span>
<span class="line"><span>  create 700 root root</span></span>
<span class="line"><span>  rotate 4</span></span>
<span class="line"><span>  compress</span></span>
<span class="line"><span>}</span></span></code></pre></div><p>在上面的配置文件中：</p><ul><li>size 1k - logrotate 僅在文件大小等於（或大於）此大小時運行。</li><li>create - 輪換原始文件並創建具有指定權限、用户和組的新文件。</li><li>rotate - 限制日誌文件輪轉的數量。因此，這將只保留最近的 4 個輪轉的日誌文件。</li><li>compress - 這將壓縮文件。</li></ul><p>第二步：通常，你需要等待一天才能等到 logrotate 由 <code>/etc/cron.daily</code> 執行。除此之外，你可以用下面的命令在命令列中運行：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>/usr/sbin/logrotate  /etc/logrotate.conf</span></span></code></pre></div><p>在執行 logrotate 命令之前的輸出：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>[root@rhel1 tmp]# ls -l /tmp/</span></span>
<span class="line"><span>total 28</span></span>
<span class="line"><span>-rw-------. 1 root root 20000 Jan 1 05:23 sample_output.log</span></span></code></pre></div><p>在執行 logrotate 之後的輸出：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>[root@rhel1 tmp]# ls -l /tmp</span></span>
<span class="line"><span>total 12</span></span>
<span class="line"><span>-rwx------. 1 root root 0 Jan 1 05:24 sample_output.log</span></span>
<span class="line"><span>-rw-------. 1 root root 599 Jan 1 05:24 sample_output.log-20170101.gz</span></span>
<span class="line"><span>[root@rhel1 tmp]#</span></span></code></pre></div><p>這樣就能確認 logrotate 成功實現了。</p><hr><p>作者簡介：</p><p>大家好！我是 Manmohan Mirkar。我很高興見到你們！我在 10 多年前開始使用 Linux，我從來沒有想過我會到今天這個地步。我的激情是幫助你們獲取 Linux 知識。謝謝你們在這！</p><hr>`,29)),o("p",null,[t[1]||(t[1]=s("via: ",-1)),e(a,{href:"http://www.linuxroutes.com/configure-logrotate/"},{default:n(()=>[...t[0]||(t[0]=[s("http://www.linuxroutes.com/configure-logrotate/",-1)])]),_:1})]),o("p",null,[t[5]||(t[5]=s("作者：",-1)),e(a,{href:"http://www.linuxroutes.com/author/admin/"},{default:n(()=>[...t[2]||(t[2]=[s("Manmohan Mirkar",-1)])]),_:1}),t[6]||(t[6]=s(" 譯者：",-1)),e(a,{href:"https://github.com/geekpi"},{default:n(()=>[...t[3]||(t[3]=[s("geekpi",-1)])]),_:1}),t[7]||(t[7]=s(" 校對：",-1)),e(a,{href:"https://github.com/wxy"},{default:n(()=>[...t[4]||(t[4]=[s("wxy",-1)])]),_:1})]),o("p",null,[t[10]||(t[10]=s("本文由 ",-1)),e(a,{href:"https://github.com/LCTT/TranslateProject"},{default:n(()=>[...t[8]||(t[8]=[s("LCTT",-1)])]),_:1}),t[11]||(t[11]=s(" 原創編譯，",-1)),e(a,{href:"https://linux.cn/"},{default:n(()=>[...t[9]||(t[9]=[s("Linux中國",-1)])]),_:1}),t[12]||(t[12]=s(" 榮譽推出",-1))])])}const C=l(d,[["render",c]]);export{x as __pageData,C as default};
